package org.jsoup.nodes;

import org.jsoup.helper.Validate;
import org.junit.Test;
import org.jsoup.internal.StringUtil;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void newNode TextNodeCreationTest() {
        TextNode newNode = new TextNode("Hello World");
        assertNotNull(newNode);
    }

    @Test
    public void nodeName TextNodeGetNodeNameTest() {
        TextNode textNode = new TextNode("Hello World");
        assertEquals("text", textNode.nodeName());
    }

    @Test
    public void getText TextNodeGetTextTest() {
        TextNode textNode = new TextNode("Hello World");
        assertNotNull(textNode.text());
    }

    @Test
    public void setText TextNodeSetTextTest() {
        TextNode textNode = new TextNode();
        textNode.setText("New Text");
        assertEquals("New Text", textNode.text());
    }

    @Test
    public void getWholeText TextNodeGetWholeTextTest() {
        TextNode textNode = new TextNode("Hello World");
        assertNotNull(textNode.getWholeText());
    }

    @Test
    public void isBlank TextNodeIsBlankTest() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());

        TextNode anotherTextNode = new TextNode("   ");
        assertTrue(anotherTextNode.isBlank());
    }

    @Test
    public void splitText TextNodeSplitTextTest() throws IOException {
        TextNode textNode = new TextNode("Hello World");
        TextNode result1 = textNode.splitText(6);
        assertNotNull(result1);

        String expectedSecondPart = "World";
        assertEquals(expectedSecondPart, result1.text());

        assertEquals("Hello", textNode.splitText(0).text());
    }

    @Test
    public void outerHtmlHead TextNodeOuterHtmlHeadTest() throws IOException {
        TextNode textNode = new TextNode("<p>Hello World!</p>");
        Appendable appendable = new StringBuilder();
        Document.OutputSettings outputSettings = null;
        textNode.outerHtmlHead(appendable, 0, outputSettings);
        assertEquals("<p>", appendable.toString());
    }

    @Test
    public void outerHtmlTail TextNodeOuterHtmlTailTest() throws IOException {
        TextNode textNode = new TextNode("<p>Hello World!</p>");
        Appendable appendable = new StringBuilder();
        Document.OutputSettings outputSettings = null;
        textNode.outerHtmlTail(appendable, 0, outputSettings);
        assertEquals("</p>", appendable.toString());
    }

    @Test
    public void clone TextNodeCloneTest() {
        TextNode originalTextNode = new TextNode("Hello World");
        TextNode clonedTextNode = originalTextNode.clone();
        assertNotNull(clonedTextNode);
        assertEquals(originalTextNode, clonedTextNode);

        String expectedText = "Hello World";
        assertEquals(expectedText, clonedTextNode.text());
    }

    @Test
    public void createFromEncoded TextNodecreateFromEncodedTest() {
        String encodedText = "Hello World";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertNotNull(textNode);
        assertEquals(encodedText, textNode.getWholeText());
    }

    @Test
    public void normaliseWhitespace NormalisesWhitespaceTest() {
        String input = "   ";
        String expectedOutput = StringUtil.normaliseWhitespace(input);
        assertEquals(expectedOutput, TextNode.normaliseWhitespace(input));
    }

    @Test
    public void stripLeadingWhitespace StripLeadingWhitespaceTest() {
        String input = "   Hello World";
        String expectedOutput = TextNode.stripLeadingWhitespace(input);
        assertEquals(expectedOutput, TextNode.stripLeadingWhitespace(input));
    }

    @Test
    public void lastCharIsWhitespace LastCharIsWhitespaceTest() {
        StringBuilder sb = new StringBuilder("Hello");
        assertTrue(TextNode.lastCharIsWhitespace(sb));
        assertFalse(TextNode.lastCharIsWhitespace(new StringBuilder()));
    }
}
